755	/****************************************************************************
756	 * Private Functions - MAC and DMA Control
757	 ****************************************************************************/
758	
759	static void set_mac_addr(uintptr_t gmac_base, const uint8_t *mac)
760	{
761	  uint32_t hi;
762	  uint32_t lo;
763	
764	  hi = (mac[5] << 8) | mac[4] | GMAC_HI_REG_AE;
765	  lo = (mac[3] << 24) | (mac[2] << 16) | (mac[1] << 8) | mac[0];
766	
767	  putreg32(hi, gmac_base + GMAC_ADDR_HIGH(0));
768	  putreg32(lo, gmac_base + GMAC_ADDR_LOW(0));
769	}
770	
771	static void start_mac_and_dma(struct sg2000_eth_priv_s *priv)
772	{
773	  uintptr_t gmac_base = priv->gmac_base;
774	  uint32_t v;
775	
776	  /* Configure MAC based on PHY negotiation results */
777	
778	  v = GMAC_CORE_INIT;
779	  if (priv->speed == 100)
780	    {
781	      v |= GMAC_CONFIG_FES;   /* 100M */
782	    }
783	
784	  if (priv->duplex)
785	    {
786	      v |= GMAC_CONFIG_DM;    /* Full duplex */
787	    }
788	
789	  /* Enable MAC TX and RX */
790	  v |= GMAC_CONFIG_TE | GMAC_CONFIG_RE;
791	
792	  putreg32(v, gmac_base + GMAC_CONFIG);
793	
794	  /* Packet filter at correct DWMAC1000 offset (0x0004, not 0x0008).
795	   * Pass multicast + broadcast + unicast (promiscuous mode).
796	   */
797	
798	  putreg32(GMAC_FILTER_HMC | GMAC_FILTER_PM | GMAC_FILTER_PR,
799	           gmac_base + GMAC_FRAME_FILTER);
800	
801	  /* Enable MAC interrupts */
802	  putreg32(GMAC_INT_DEFAULT, gmac_base + GMAC_INT_MASK);
803	
804	  /* Enable DMA interrupts via CSR7 */
805	  putreg32(DMA_INTR_DEFAULT_MASK, gmac_base + DMA_INTR_ENA);
806	
807	  /* Start TX and RX DMA via CSR6 (single control register for DWMAC1000):
808	   * TSF (TX Store and Forward) + RSF (RX Store and Forward) +
809	   * OSF (Operate on Second Frame) + ST (Start TX) + SR (Start RX)
810	   */
811	
812	  putreg32(DMA_CONTROL_TSF | DMA_CONTROL_RSF | DMA_CONTROL_OSF |
813	           DMA_CONTROL_ST | DMA_CONTROL_SR,
814	           gmac_base + DMA_CONTROL);
815	}
