817	/****************************************************************************
818	 * Private Functions - Doorbell Helpers
819	 ****************************************************************************/
820	
821	static void tx_doorbell(struct sg2000_eth_priv_s *priv)
822	{
823	  /* DWMAC1000: write any value to DMA_XMT_POLL_DEMAND (CSR1) to trigger
824	   * the TX DMA engine to re-fetch descriptors from the TX descriptor ring.
825	   */
826	
827	  putreg32(1, priv->gmac_base + DMA_XMT_POLL_DEMAND);
828	}
829	
830	static void rx_doorbell(struct sg2000_eth_priv_s *priv)
831	{
832	  /* DWMAC1000: write any value to DMA_RCV_POLL_DEMAND (CSR2) to trigger
833	   * the RX DMA engine to re-fetch descriptors from the RX descriptor ring.
834	   */
835	
836	  putreg32(1, priv->gmac_base + DMA_RCV_POLL_DEMAND);
837	}
