1026	/****************************************************************************
1027	 * Name: netdriver_ifup
1028	 *
1029	 * Description:
1030	 *   OpenVela netdev_ops_s ifup callback.  Starts the network device.
1031	 *
1032	 ****************************************************************************/
1033	
1034	static int netdriver_ifup(FAR struct netdev_lowerhalf_s *dev)
1035	{
1036	  FAR struct sg2000_eth_priv_s *priv =
1037	      (FAR struct sg2000_eth_priv_s *)dev;
1038	  int ret;
1039	
1040	  syslog(LOG_INFO, "sg2000_eth: ifup begin\n");
1041	
1042	  /* Ensure GMAC clocks and resets are configured */
1043	
1044	  gmac_clock_enable();
1045	
1046	  /* Set MAC core init (includes PS=MII mode) before PHY/MDIO operations. */
1047	
1048	  putreg32(GMAC_CORE_INIT, priv->gmac_base + GMAC_CONFIG);
1049	
1050	  ephy_hardware_reset(priv->phy_base, priv->phy_top);
1051	  up_mdelay(10);
1052	
1053	  ret = mdio_verify_phy(priv->gmac_base);
1054	  if (ret < 0)
1055	    {
1056	      nerr("ERROR: MDIO PHY not responding: %d\n", ret);
1057	      return ret;
1058	    }
1059	
1060	  syslog(LOG_INFO, "sg2000_eth: MDIO operational "
1061	         "mdio_addr=0x%08" PRIX32 " mdio_data=0x%08" PRIX32 "\n",
1062	         getreg32(priv->gmac_base + GMAC_MII_ADDR),
1063	         getreg32(priv->gmac_base + GMAC_MII_DATA));
1064	
1065	  ephy_full_tuning(priv->phy_base, priv->phy_top);
1066	
1067	  ret = phy_config_init(priv);
1068	  if (ret < 0)
1069	    {
1070	      nerr("ERROR: PHY init failed: %d\n", ret);
1071	      return ret;
1072	    }
1073	
1074	  ret = dma_soft_reset(priv->gmac_base);
1075	  if (ret < 0)
1076	    {
1077	      syslog(LOG_ERR, "sg2000_eth: DMA reset failed after PHY/MDIO "
1078	             "diagnostics: %d\n", ret);
1079	      return ret;
1080	    }
1081	
1082	  if (priv->tx_desc == NULL || priv->rx_desc == NULL)
1083	    {
1084	      ret = alloc_dma(priv);
1085	      if (ret < 0)
1086	        {
1087	          nerr("ERROR: alloc_dma failed: %d\n", ret);
1088	          return ret;
1089	        }
1090	    }
1091	
1092	  init_desc_and_dma(priv);
1093	  set_mac_addr(priv->gmac_base, priv->mac_addr);
1094	  start_mac_and_dma(priv);
1095	  rx_doorbell(priv);
1096	
1097	  /* Diagnostic: verify DMA state machines after initialization.
1098	   * TS[22:20]=TX state, RS[19:17]=RX state.  Both should show Running.
1099	   */
1100	
1101	  {
1102	    uint32_t csr5 = getreg32(priv->gmac_base + DMA_STATUS);
1103	    uint32_t csr6 = getreg32(priv->gmac_base + DMA_CONTROL);
1104	    unsigned int tx_state = (csr5 >> 20) & 0x7;
1105	    unsigned int rx_state = (csr5 >> 17) & 0x7;
1106	    static const char * const states[] = {
1107	      "Stopped", "Running(FetchDesc)", "Running(WaitEnd)",
1108	      "Running(ReadData/RxWait)", "Suspended(RxUnavail)",
1109	      "Running(CloseDesc)", "Running(FlushRx)", "Running(QueueRx)"
1110	    };
1111	
1112	    syslog(LOG_INFO,
1113	           "sg2000_eth: DMA state CSR5=0x%08" PRIX32
1114	           " CSR6=0x%08" PRIX32 "\n"
1115	           "  TX_FSM=%u(%s) RX_FSM=%u(%s)\n"
1116	           "  TX_DESC[0]=0x%08" PRIX32 " RX_DESC[0]=0x%08" PRIX32 "\n",
1117	           csr5, csr6,
1118	           tx_state, states[tx_state],
1119	           rx_state, states[rx_state],
1120	           priv->tx_desc[0].des0, priv->rx_desc[0].des0);
1121	  }
1122	
1123	  up_enable_irq(priv->irq);
1124	  netdev_lower_carrier_on(dev);
1125	
1126	  syslog(LOG_INFO, "sg2000_eth: ifup done, %d Mbps %s duplex\n",
1127	         priv->speed, priv->duplex ? "Full" : "Half");
1128	
1129	  return OK;
1130	}
