1132	/****************************************************************************
1133	 * Name: netdriver_ifdown
1134	 *
1135	 * Description:
1136	 *   OpenVela netdev_ops_s ifdown callback.  Stops the network device.
1137	 *
1138	 ****************************************************************************/
1139	
1140	static int netdriver_ifdown(FAR struct netdev_lowerhalf_s *dev)
1141	{
1142	  FAR struct sg2000_eth_priv_s *priv =
1143	      (FAR struct sg2000_eth_priv_s *)dev;
1144	  uint32_t v;
1145	
1146	  up_disable_irq(priv->irq);
1147	
1148	  /* Stop TX and RX DMA via CSR6 (DMA_CONTROL at 0x1018).
1149	   * Clear ST (bit 13) and SR (bit 1).
1150	   */
1151	
1152	  v = getreg32(priv->gmac_base + DMA_CONTROL);
1153	  putreg32(v & ~(DMA_CONTROL_ST | DMA_CONTROL_SR),
1154	           priv->gmac_base + DMA_CONTROL);
1155	
1156	  /* Disable MAC TX/RX */
1157	
1158	  v = getreg32(priv->gmac_base + GMAC_CONFIG);
1159	  putreg32(v & ~(GMAC_CONFIG_TE | GMAC_CONFIG_RE),
1160	           priv->gmac_base + GMAC_CONFIG);
1161	
1162	  netdev_lower_carrier_off(dev);
1163	
1164	  ninfo("netdriver_ifdown: interface down\n");
1165	
1166	  return OK;
1167	}
