1169	/****************************************************************************
1170	 * Name: netdriver_transmit
1171	 *
1172	 * Description:
1173	 *   OpenVela netdev_ops_s transmit callback.  Sends a packet.
1174	 *   The driver takes ownership of the netpkt and MUST free it after TX
1175	 *   completion (or on error).
1176	 *
1177	 *   Returned Value:
1178	 *     OK on success (pkt queued for TX); negated errno on failure.
1179	 *
1180	 ****************************************************************************/
1181	
1182	static int netdriver_transmit(FAR struct netdev_lowerhalf_s *dev,
1183	                               FAR netpkt_t *pkt)
1184	{
1185	  FAR struct sg2000_eth_priv_s *priv =
1186	      (FAR struct sg2000_eth_priv_s *)dev;
1187	  unsigned int len = netpkt_getdatalen(dev, pkt);
1188	  uint8_t tmp_buf[SG2000_ETH_BUFSIZE];
1189	  const uint8_t *data;
1190	  int ret;
1191	
1192	  if (len > SG2000_ETH_BUFSIZE)
1193	    {
1194	      nerr("ERROR: TX packet too large: %u\n", len);
1195	      netpkt_free(dev, pkt, NETPKT_TX);
1196	      return -E2BIG;
1197	    }
1198	
1199	  /* Extract data from netpkt.  If fragmented, copy out; else use pointer. */
1200	
1201	  if (netpkt_is_fragmented(pkt))
1202	    {
1203	      netpkt_copyout(dev, tmp_buf, pkt, len, 0);
1204	      data = tmp_buf;
1205	    }
1206	  else
1207	    {
1208	      data = netpkt_getdata(dev, pkt);
1209	      if (!data)
1210	        {
1211	          nerr("ERROR: netpkt_getdata returned NULL\n");
1212	          netpkt_free(dev, pkt, NETPKT_TX);
1213	          return -EINVAL;
1214	        }
1215	    }
1216	
1217	  /* Send via DMA */
1218	
1219	  ret = hw_transmit(priv, data, len);
1220	  if (ret < 0)
1221	    {
1222	      nerr("ERROR: hw_transmit failed: %d\n", ret);
1223	      netpkt_free(dev, pkt, NETPKT_TX);
1224	      return ret;
1225	    }
1226	
1227	  /* Track this packet: store it so tx_cleanup can free it after DMA done.
1228	   * The tx_cur was already advanced by hw_transmit, so use (tx_cur - 1).
1229	   */
1230	
1231	  {
1232	    irqstate_t flags = up_irq_save();
1233	    unsigned int slot = (priv->tx_cur - 1) & (TX_RING_SIZE - 1);
1234	
1235	    priv->tx_pkt[slot] = pkt;
1236	    up_irq_restore(flags);
1237	  }
1238	
1239	  return OK;
1240	}
