1242	/****************************************************************************
1243	 * Name: netdriver_receive
1244	 *
1245	 * Description:
1246	 *   OpenVela netdev_ops_s receive callback.  Called by upper half when
1247	 *   netdev_lower_rxready() was signaled.  Returns one received packet, or
1248	 *   NULL if no more packets are available.
1249	 *
1250	 *   Returned Value:
1251	 *     A netpkt_t * containing the received packet, or NULL.
1252	 *
1253	 ****************************************************************************/
1254	
1255	static FAR netpkt_t *netdriver_receive(FAR struct netdev_lowerhalf_s *dev)
1256	{
1257	  FAR struct sg2000_eth_priv_s *priv =
1258	      (FAR struct sg2000_eth_priv_s *)dev;
1259	  FAR netpkt_t *pkt = NULL;
1260	  struct sg2000_dma_desc_s *desc;
1261	  uint32_t status;
1262	  int frame_len;
1263	  int ret;
1264	
1265	  /* Check if there is a completed RX descriptor */
1266	
1267	  desc = &priv->rx_desc[priv->rx_cur];
1268	  if (desc->des0 & DESC_OWN)
1269	    {
1270	      /* DMA still owns it, no packet ready yet.
1271	       * This can happen if rxready was signaled for a previous packet
1272	       * that was already consumed, or in edge cases.
1273	       */
1274	
1275	      return NULL;
1276	    }
1277	
1278	  status = desc->des0;
1279	
1280	  /* Check for errors */
1281	
1282	  if (status & RX_DESC_ES)
1283	    {
1284	      nerr("ERROR: RX error, status=0x%08" PRIX32 "\n", status);
1285	      goto refill;
1286	    }
1287	
1288	  /* Get frame length.  GMAC_CONFIG_ACS is set, so the hardware
1289	   * already strips the FCS; the length from the descriptor is the
1290	   * actual frame length without CRC.
1291	   */
1292	
1293	  frame_len = ((status >> RX_DESC_FL_SHIFT) & RX_DESC_FL_MASK);
1294	
1295	  if (frame_len <= 0 || frame_len > CONFIG_NET_ETH_PKTSIZE)
1296	    {
1297	      nwarn("WARNING: Invalid RX frame length: %d\n", frame_len);
1298	      goto refill;
1299	    }
1300	
1301	  /* Allocate a netpkt for the received data */
1302	
1303	  pkt = netpkt_alloc(dev, NETPKT_RX);
1304	  if (!pkt)
1305	    {
1306	      nerr("ERROR: netpkt_alloc failed\n");
1307	      goto refill;
1308	    }
1309	
1310	  /* Copy data from DMA RX buffer into the netpkt */
1311	
1312	  ret = netpkt_copyin(dev, pkt, priv->rx_buf[priv->rx_cur], frame_len, 0);
1313	  if (ret < 0)
1314	    {
1315	      nerr("ERROR: netpkt_copyin failed: %d\n", ret);
1316	      netpkt_free(dev, pkt, NETPKT_RX);
1317	      goto refill;
1318	    }
1319	
1320	refill:
1321	  /* Return the descriptor to DMA (set OWN=1).
1322	   * Preserve RER (RX End of Ring) bit in des1 if set during init.
1323	   */
1324	
1325	  desc->des0 = DESC_OWN;
1326	  desc->des1 = RX_BUF_SIZE | (desc->des1 & RX_DESC_RER);
1327	
1328	  priv->rx_cur = (priv->rx_cur + 1) & (RX_RING_SIZE - 1);
1329	  rx_doorbell(priv);
1330	
1331	  return pkt;
1332	}
