1334	/****************************************************************************
1335	 * Private Data - Operations Structure
1336	 *
1337	 * The netdev_ops_s maps our callbacks to the OpenVela lowerhalf API.
1338	 ****************************************************************************/
1339	
1340	static const struct netdev_ops_s g_ops =
1341	{
1342	  netdriver_ifup,     /* ifup */
1343	  netdriver_ifdown,   /* ifdown */
1344	  netdriver_transmit, /* transmit */
1345	  netdriver_receive   /* receive */
1346	  /* addmac, rmmac, ioctl, reclaim are not implemented for this simple
1347	   * Ethernet MAC driver.  They are only required for Wi-Fi or advanced
1348	   * filtering scenarios.
1349	   */
1350	};
