1356	/****************************************************************************
1357	 * Name: sg2000_eth_initialize
1358	 *
1359	 * Description:
1360	 *   Initialize the SG2000 Ethernet driver and register it with the OpenVela
1361	 *   network stack as a netdev_lowerhalf_s device.
1362	 *
1363	 *   Called from board_late_initialize() during system bringup.
1364	 *
1365	 ****************************************************************************/
1366	
1367	int sg2000_eth_initialize(void)
1368	{
1369	  FAR struct sg2000_eth_priv_s *priv = &g_eth_priv;
1370	  FAR struct netdev_lowerhalf_s *dev = &priv->dev;
1371	  int ret;
1372	
1373	  if (g_eth_initialized)
1374	    {
1375	      ninfo("SG2000 Ethernet driver already initialized\n");
1376	      return OK;
1377	    }
1378	
1379	  memset(priv, 0, sizeof(*priv));
1380	  priv->gmac_base = SG2000_GMAC_BASE;
1381	  priv->phy_base = SG2000_EPHY_BASE;
1382	  priv->phy_top = SG2000_EPHY_TOP;
1383	
1384	  /* Set a test MAC address (should be replaced with eFuse/OTP value) */
1385	
1386	  priv->mac_addr[0] = 0x02;
1387	  priv->mac_addr[1] = 0x00;
1388	  priv->mac_addr[2] = 0x00;
1389	  priv->mac_addr[3] = 0x00;
1390	  priv->mac_addr[4] = 0x00;
1391	  priv->mac_addr[5] = 0x01;
1392	
1393	  memcpy(dev->netdev.d_mac.ether.ether_addr_octet, priv->mac_addr,
1394	         IFHWADDRLEN);
1395	
1396	  dev->quota[NETPKT_TX] = TX_RING_SIZE / 2;
1397	  dev->quota[NETPKT_RX] = RX_RING_SIZE / 2;
1398	  dev->ops              = &g_ops;
1399	
1400	  priv->irq = SG2000_IRQ_GMAC;
1401	
1402	  ret = netdev_lower_register(dev, NET_LL_ETHERNET);
1403	  if (ret < 0)
1404	    {
1405	      nerr("ERROR: netdev_lower_register failed: %d\n", ret);
1406	      return ret;
1407	    }
1408	
1409	  netdev_lower_carrier_off(dev);
1410	  g_eth_initialized = true;
1411	  ninfo("SG2000 Ethernet driver registered as eth0 (lowerhalf)\n");
1412	
1413	  gmac_clock_enable();
1414	
1415	  ret = irq_attach(priv->irq, sg2000_eth_isr, priv);
1416	  if (ret < 0)
1417	    {
1418	      nerr("ERROR: irq_attach failed: %d\n", ret);
1419	      return OK;
1420	    }
1421	
1422	  up_enable_irq(priv->irq);
1423	  ninfo("IRQ %d enabled\n", priv->irq);
1424	
1425	  return OK;
1426	}
